const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/workflows/instances',
  headers: {'content-type': 'application/json'},
  body: {
    tool_type: 'generic_tool_item',
    tool_subtype: '-123',
    item_id: '483',
    template_id: '534',
    preset_id: '876'
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/workflows/instances"),
    Content = new StringContent("{\"tool_type\":\"generic_tool_item\",\"tool_subtype\":\"-123\",\"item_id\":\"483\",\"template_id\":\"534\",\"preset_id\":\"876\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

